import { useEffect, useState } from 'react';
import './ParticlesCustomizer.css';

const ParticlesCustomizer = ({ isOpen, onClose, onSettingsChange }) => {
  const [settings, setSettings] = useState({
    color: '#ffffff',
    count: 200,
    spread: 10,
    speed: 0.1,
    baseSize: 100,
    mouseInteraction: true,
    particleTransparency: true,
    disableRotation: true
  });

  useEffect(() => {
    if (onSettingsChange) {
      onSettingsChange(settings);
    }
  }, [settings, onSettingsChange]);

  const handleSliderChange = (key, value) => {
    setSettings(prev => ({
      ...prev,
      [key]: parseFloat(value)
    }));
  };

  const handleToggleChange = (key) => {
    setSettings(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handleColorChange = (e) => {
    setSettings(prev => ({
      ...prev,
      color: e.target.value
    }));
  };

  if (!isOpen) return null;

  return (
    <div className="particles-customizer-overlay" onClick={onClose}>
      <div className="particles-customizer-panel" onClick={(e) => e.stopPropagation()}>
        <div className="customizer-header">
          <h2 className="customizer-title">Customize</h2>
          <button className="customizer-close" onClick={onClose}>×</button>
        </div>

        <div className="customizer-controls">
          {/* Color Control */}
          <div className="control-group">
            <label className="control-label">Color</label>
            <div className="color-control">
              <input
                type="color"
                value={settings.color}
                onChange={handleColorChange}
                className="color-input"
              />
              <div className="color-preview" style={{ backgroundColor: settings.color }}></div>
            </div>
          </div>

          {/* Count Slider */}
          <div className="control-group">
            <label className="control-label">Count</label>
            <div className="slider-control">
              <input
                type="range"
                min="50"
                max="1000"
                value={settings.count}
                onChange={(e) => handleSliderChange('count', e.target.value)}
                className="slider"
              />
              <span className="slider-value">{settings.count}</span>
            </div>
          </div>

          {/* Spread Slider */}
          <div className="control-group">
            <label className="control-label">Spread</label>
            <div className="slider-control">
              <input
                type="range"
                min="1"
                max="50"
                value={settings.spread}
                onChange={(e) => handleSliderChange('spread', e.target.value)}
                className="slider"
              />
              <span className="slider-value">{settings.spread}</span>
            </div>
          </div>

          {/* Speed Slider */}
          <div className="control-group">
            <label className="control-label">Speed</label>
            <div className="slider-control">
              <input
                type="range"
                min="0.01"
                max="1"
                step="0.01"
                value={settings.speed}
                onChange={(e) => handleSliderChange('speed', e.target.value)}
                className="slider"
              />
              <span className="slider-value">{settings.speed}</span>
            </div>
          </div>

          {/* Base Size Slider */}
          <div className="control-group">
            <label className="control-label">Base Size</label>
            <div className="slider-control">
              <input
                type="range"
                min="10"
                max="300"
                value={settings.baseSize}
                onChange={(e) => handleSliderChange('baseSize', e.target.value)}
                className="slider"
              />
              <span className="slider-value">{settings.baseSize}</span>
            </div>
          </div>

          {/* Mouse Interaction Toggle */}
          <div className="control-group">
            <label className="control-label">Mouse Interaction</label>
            <div className="toggle-control">
              <label className="toggle-switch">
                <input
                  type="checkbox"
                  checked={settings.mouseInteraction}
                  onChange={() => handleToggleChange('mouseInteraction')}
                />
                <span className="toggle-slider"></span>
              </label>
            </div>
          </div>

          {/* Particle Transparency Toggle */}
          <div className="control-group">
            <label className="control-label">Particle Transparency</label>
            <div className="toggle-control">
              <label className="toggle-switch">
                <input
                  type="checkbox"
                  checked={settings.particleTransparency}
                  onChange={() => handleToggleChange('particleTransparency')}
                />
                <span className="toggle-slider"></span>
              </label>
            </div>
          </div>

          {/* Disable Rotation Toggle */}
          <div className="control-group">
            <label className="control-label">Disable Rotation</label>
            <div className="toggle-control">
              <label className="toggle-switch">
                <input
                  type="checkbox"
                  checked={settings.disableRotation}
                  onChange={() => handleToggleChange('disableRotation')}
                />
                <span className="toggle-slider"></span>
              </label>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ParticlesCustomizer;
